import { mkdir, rename, rm } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';

import type { BlobStore } from './types';

/** Keys are generated by the file service; anything else never reaches the disk. */
const SAFE_KEY = /^[a-z0-9-]{8,64}$/;

/**
 * A directory on this machine. Files are spread over subdirectories by the
 * first two characters of their key, so no single directory grows without
 * bound. With several instances the directory must be one they all see (a
 * shared volume) — otherwise use `s3`.
 */
export function createLocalBlobStore(directory: string): BlobStore {
  const root = resolve(directory);
  const pathOf = (key: string): string | null =>
    SAFE_KEY.test(key) ? join(root, key.slice(0, 2), key) : null;

  return {
    async put(key, bytes) {
      const path = pathOf(key);
      if (!path) throw new Error(`not a storage key: ${key}`);
      await mkdir(dirname(path), { recursive: true });
      // Written beside the target and renamed into place, so a reader never
      // sees half a file and a crash leaves no file under the real name.
      const partial = `${path}.partial`;
      await Bun.write(partial, bytes);
      await rename(partial, path);
      return key;
    },

    async get(ref) {
      const path = pathOf(ref);
      if (!path) return null;
      const file = Bun.file(path);
      return (await file.exists()) ? file : null;
    },

    async delete(ref) {
      const path = pathOf(ref);
      if (path) await rm(path, { force: true });
    },
  };
}
